mapper.select:
SELECT u.USUARIO_PAGO AS usuarioPagoId, u.USUARIO_PAGO AS usuarioPagoNombre,
/* --- PAGOS por turno --- */ COALESCE(SUM(CASE WHEN u.BO_IS_PAGO = TRUE AND HOUR(u.FC_PAGO) BETWEEN 6 AND 12 THEN u.VL_PAGO ELSE 0 END), 0) AS montoDiaPagos, COALESCE(SUM(CASE WHEN u.BO_IS_PAGO = TRUE AND HOUR(u.FC_PAGO) BETWEEN 13 AND 18 THEN u.VL_PAGO ELSE 0 END), 0) AS montoTardePagos, COALESCE(SUM(CASE WHEN u.BO_IS_PAGO = TRUE AND (HOUR(u.FC_PAGO) >= 19 OR HOUR(u.FC_PAGO) <= 5) THEN u.VL_PAGO ELSE 0 END), 0) AS montoNochePagos, COALESCE(SUM(CASE WHEN u.BO_IS_PAGO = TRUE AND HOUR(u.FC_PAGO) BETWEEN 6 AND 12 THEN 1 ELSE 0 END), 0) AS cantDiaPagos, COALESCE(SUM(CASE WHEN u.BO_IS_PAGO = TRUE AND HOUR(u.FC_PAGO) BETWEEN 13 AND 18 THEN 1 ELSE 0 END), 0) AS cantTardePagos, COALESCE(SUM(CASE WHEN u.BO_IS_PAGO = TRUE AND (HOUR(u.FC_PAGO) >= 19 OR HOUR(u.FC_PAGO) <= 5) THEN 1 ELSE 0 END), 0) AS cantNochePagos, /* --- EXONERADOS por turno (sin monto) --- */ COALESCE(SUM(CASE WHEN u.BO_EXONERADO = TRUE AND HOUR(u.FC_PAGO) BETWEEN 6 AND 12 THEN 1 ELSE 0 END), 0) AS cantDiaEx, COALESCE(SUM(CASE WHEN u.BO_EXONERADO = TRUE AND HOUR(u.FC_PAGO) BETWEEN 13 AND 18 THEN 1 ELSE 0 END), 0) AS cantTardeEx, COALESCE(SUM(CASE WHEN u.BO_EXONERADO = TRUE AND (HOUR(u.FC_PAGO) >= 19 OR HOUR(u.FC_PAGO) <= 5) THEN 1 ELSE 0 END), 0) AS cantNocheEx
FROM SYS_USUARIO u
u.BO_CONGRESISTA = TRUE
AND u.FC_PAGO >= #{desde}
AND u.FC_PAGO <= #{hasta}
GROUP BY u.USUARIO_PAGO ORDER BY (montoDiaPagos + montoTardePagos + montoNochePagos) DESC
